    const n = g.attributes.position.count, col = new Float32Array(n * 3); _c.set(o.c ?? 0xffffff); for (let i = 0; i < n; i++) { col[i * 3] = _c.r; col[i * 3 + 1] = _c.g; col[i * 3 + 2] = _c.b; }
